def think(thought, **_extra):
    import json, os, datetime, time, hashlib, base64, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0458000" if __import__("os").path.isdir("./environment_mix/0458000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _day_bucket(dt):
        d = dt.astimezone(datetime.timezone.utc).date()
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)

    def _parse_cursor(s):
        try:
            raw = base64.urlsafe_b64decode(s.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _get_client_request_id():
        # Middleware may pass this through ambient extras
        for k in ("client_request_id", "idempotency_key", "request_id"):
            v = _extra.get(k)
            if isinstance(v, str) and v.strip():
                return v.strip()
        return None

    def _get_ip_ua():
        ip = _extra.get("ip_address") or _extra.get("ip") or _extra.get("remote_addr")
        ua = _extra.get("user_agent") or _extra.get("ua")
        if ip is not None and not isinstance(ip, str):
            ip = None
        if ua is not None and not isinstance(ua, str):
            ua = None
        return ip, ua

    def _resolve_auth():
        """
        Ambient auth: select an api_keys row with status=active whose workspace is active.
        If an explicit credential is present in extras, match it by id OR key_prefix (client-visible).
        """
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")

        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}
        cred = _extra.get("api_key") or _extra.get("api_key_id") or _extra.get("key")

        candidates = []
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if not ws or ws.get("status") != "active":
                continue
            candidates.append((k, ws))

        if cred is None:
            return candidates[0] if candidates else (None, None)

        if not isinstance(cred, str) or not cred.strip():
            return (None, None)
        cred = cred.strip()

        # Authenticate by matching id or key_prefix (client-visible), never key_hash.
        for k, ws in candidates:
            if cred == k.get("id") or cred == k.get("key_prefix"):
                return (k, ws)

        return (None, None)

    def _log_request(endpoint, api_key_id, workspace_id, status, started_ts):
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        now = time.time()
        latency_ms = int(round((now - started_ts) * 1000))
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "status": status,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        reqs.append(row)
        _save("request_logs.json", reqs)

    started = time.time()
    endpoint = "think"

    # Validate input
    if not isinstance(thought, str):
        try:
            _log_request(endpoint, None, None, "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "`thought` must be a string.")
    trimmed = thought.strip()
    if trimmed == "":
        try:
            _log_request(endpoint, None, None, "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "`thought` must not be empty or whitespace.")

    api_key, ws = _resolve_auth()
    if not api_key or not ws:
        try:
            _log_request(endpoint, None, None, "UNAUTHORIZED", started)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "Missing or invalid API key, or workspace not active.")

    # Enforce max_thought_chars
    max_chars = ws.get("max_thought_chars")
    if not isinstance(max_chars, int):
        try:
            _log_request(endpoint, api_key.get("id"), ws.get("id"), "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Workspace configuration invalid: max_thought_chars.")
    if len(thought) > max_chars:
        try:
            _log_request(endpoint, api_key.get("id"), ws.get("id"), "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Thought exceeds workspace max_thought_chars.", max_thought_chars=max_chars)

    # Idempotency via middleware-provided client_request_id (if present)
    client_request_id = _get_client_request_id()

    thought_logs = _load("thought_logs.json")
    if not isinstance(thought_logs, list):
        thought_logs = []

    if client_request_id is not None:
        for tl in thought_logs:
            if not isinstance(tl, dict):
                continue
            if tl.get("workspace_id") == ws.get("id") and tl.get("client_request_id") == client_request_id:
                # Successful idempotent return: do not create another row; do not increment usage.
                try:
                    _log_request(endpoint, api_key.get("id"), ws.get("id"), "OK_IDEMPOTENT", started)
                except Exception:
                    pass
                return {
                    "thought_log": tl,
                    "idempotent_replay": True,
                }

    # Quota/rate checks: daily limits at workspace-total usage row
    usage = _load("usage_daily.json")
    if not isinstance(usage, list):
        usage = []

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    bucket = _day_bucket(now_dt)
    bucket_iso = bucket.isoformat()

    ws_id = ws.get("id")
    key_id = api_key.get("id")

    def _find_usage_row(workspace_id, api_key_id, usage_date_iso):
        for r in usage:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") == workspace_id and r.get("api_key_id") == api_key_id and r.get("usage_date") == usage_date_iso:
                return r
        return None

    ws_total = _find_usage_row(ws_id, None, bucket_iso)
    ws_calls = int(ws_total.get("think_calls", 0)) if isinstance(ws_total, dict) else 0
    ws_chars = int(ws_total.get("thought_chars", 0)) if isinstance(ws_total, dict) else 0

    daily_thought_limit = ws.get("daily_thought_limit")
    daily_char_limit = ws.get("daily_char_limit")
    if not isinstance(daily_thought_limit, int) or daily_thought_limit < 1:
        try:
            _log_request(endpoint, key_id, ws_id, "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Workspace configuration invalid: daily_thought_limit.")
    if not isinstance(daily_char_limit, int) or daily_char_limit < 1:
        try:
            _log_request(endpoint, key_id, ws_id, "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Workspace configuration invalid: daily_char_limit.")

    new_chars = len(thought)
    if ws_calls + 1 > daily_thought_limit:
        try:
            _log_request(endpoint, key_id, ws_id, "QUOTA_EXCEEDED", started)
        except Exception:
            pass
        return _err("QUOTA_EXCEEDED", "Daily thought call limit exceeded.", limit=daily_thought_limit)
    if ws_chars + new_chars > daily_char_limit:
        try:
            _log_request(endpoint, key_id, ws_id, "QUOTA_EXCEEDED", started)
        except Exception:
            pass
        return _err("QUOTA_EXCEEDED", "Daily thought character limit exceeded.", limit=daily_char_limit)

    # Create thought log row
    thought_sha256 = hashlib.sha256(thought.encode("utf-8")).hexdigest()
    ip, ua = _get_ip_ua()
    now_iso = _now_iso()
    thought_log_id = "tl_" + uuid.uuid4().hex
    new_row = {
        "id": thought_log_id,
        "workspace_id": ws_id,
        "api_key_id": key_id,
        "status": "recorded",
        "thought": thought,
        "thought_sha256": thought_sha256,
        "thought_chars": new_chars,
        "client_request_id": client_request_id,
        "ip_address": ip,
        "user_agent": ua,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Enforce unique(workspace_id, client_request_id) where not null
    if client_request_id is not None:
        for tl in thought_logs:
            if not isinstance(tl, dict):
                continue
            if tl.get("workspace_id") == ws_id and tl.get("client_request_id") == client_request_id:
                try:
                    _log_request(endpoint, key_id, ws_id, "CONFLICT", started)
                except Exception:
                    pass
                return _err("CONFLICT", "Duplicate client_request_id within workspace.", client_request_id=client_request_id)

    # Persist thought_logs
    thought_logs.append(new_row)
    _save("thought_logs.json", thought_logs)

    # Atomically increment usage for (workspace_id, api_key_id, date) and (workspace_id, null, date)
    def _ensure_usage(workspace_id, api_key_id, usage_date_iso):
        r = _find_usage_row(workspace_id, api_key_id, usage_date_iso)
        if r is not None:
            return r
        r = {
            "id": "ud_" + uuid.uuid4().hex,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "usage_date": usage_date_iso,
            "think_calls": 0,
            "thought_chars": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage.append(r)
        return r

    r_key = _ensure_usage(ws_id, key_id, bucket_iso)
    r_ws = _ensure_usage(ws_id, None, bucket_iso)

    r_key["think_calls"] = int(r_key.get("think_calls", 0)) + 1
    r_key["thought_chars"] = int(r_key.get("thought_chars", 0)) + new_chars
    r_key["updated_at"] = now_iso

    r_ws["think_calls"] = int(r_ws.get("think_calls", 0)) + 1
    r_ws["thought_chars"] = int(r_ws.get("thought_chars", 0)) + new_chars
    r_ws["updated_at"] = now_iso

    _save("usage_daily.json", usage)

    # Update api_key last_used_at
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_id:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)

    try:
        _log_request(endpoint, key_id, ws_id, "OK", started)
    except Exception:
        pass

    return {"thought_log": new_row}

def workspaces_list(status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0458000" if __import__("os").path.isdir("./environment_mix/0458000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso_z():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _log_request(endpoint, api_key_id, workspace_id, status_code, started_ts, error_code=None):
        # Best-effort request logging if the collection exists; never fail the request because logging failed.
        try:
            reqs = _load("request_logs.json")
            if not isinstance(reqs, list):
                reqs = []
            latency_ms = int(round((time.time() - started_ts) * 1000))
            row = {
                "id": "tt_req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": status_code,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "created_at": _now_iso_z(),
            }
            reqs.append(row)
            _save("request_logs.json", reqs)
        except Exception:
            return

    started = time.time()
    endpoint = "workspaces_list"

    # ---- Validate inputs ----
    if status is not None:
        if not isinstance(status, str):
            _log_request(endpoint, None, None, 400, started, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid type for status.")
        if status not in ("active", "suspended", "deleted"):
            _log_request(endpoint, None, None, 400, started, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.", allowed=["active", "suspended", "deleted"])

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log_request(endpoint, None, None, 400, started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid type for limit.")
    if limit < 1 or limit > 200:
        _log_request(endpoint, None, None, 400, started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit out of range.", minimum=1, maximum=200)

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        _log_request(endpoint, None, None, 400, started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    # ---- Resolve ambient authentication (must find a workable active key -> active workspace pair) ----
    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    if not isinstance(api_keys, list):
        api_keys = []
    if not isinstance(workspaces, list):
        workspaces = []

    ws_by_id = {}
    for w in workspaces:
        if isinstance(w, dict) and isinstance(w.get("id"), str):
            ws_by_id[w["id"]] = w

    # Determine presented credential if any. (If none, we must still authenticate via any usable active key.)
    cred = _extra.get("api_key")
    if cred is None:
        cred = _extra.get("api_key_id")
    if cred is None:
        cred = _extra.get("key")

    cred = cred.strip() if isinstance(cred, str) else None

    candidates = []
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        ws = ws_by_id.get(k.get("workspace_id"))
        if not isinstance(ws, dict):
            continue
        if ws.get("status") != "active":
            continue
        # If a credential is presented, it must match a client-visible value: id or key_prefix.
        if cred is not None:
            if cred != k.get("id") and cred != k.get("key_prefix"):
                continue
        candidates.append((k, ws))

    if not candidates:
        _log_request(endpoint, None, None, 401, started, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Unauthorized.")

    # Select the resolved context deterministically
    candidates.sort(key=lambda pair: (str(pair[1].get("id") or ""), str(pair[0].get("id") or "")))
    api_key_row, authed_ws = candidates[0]
    api_key_id = api_key_row.get("id")
    workspace_id = authed_ws.get("id")

    # ---- Visibility rule: typically only its own workspace ----
    visible = [authed_ws]

    # Apply status filter (still within visibility)
    if status is not None:
        visible = [w for w in visible if w.get("status") == status]

    # Stable sort by id for pagination
    visible.sort(key=lambda w: str(w.get("id") or ""))

    # ---- Cursor handling ----
    # Cursor is an opaque token from vendor; in this local server we accept either:
    # - a raw workspace id to start-after, OR
    # - a JSON/base64-like string from old implementations; if it contains {"after_id": "..."} we honor it.
    after_id = None
    if cursor is not None:
        c = cursor.strip()

        # Accept raw id (the audit shows callers are sending a workspace id as cursor).
        after_id = c

        # Try to decode JSON if it looks like JSON; do not error if it doesn't.
        if c.startswith("{") and c.endswith("}"):
            try:
                obj = json.loads(c)
                if isinstance(obj, dict) and isinstance(obj.get("after_id"), str) and obj["after_id"].strip():
                    after_id = obj["after_id"].strip()
            except Exception:
                pass

        # Also attempt URL-safe base64 JSON decode; do not treat failures as invalid cursor.
        if after_id == c:
            try:
                # pad base64
                pad = "=" * ((4 - (len(c) % 4)) % 4)
                raw = __import__("base64").urlsafe_b64decode((c + pad).encode("utf-8"))
                obj = json.loads(raw.decode("utf-8"))
                if isinstance(obj, dict) and isinstance(obj.get("after_id"), str) and obj["after_id"].strip():
                    after_id = obj["after_id"].strip()
            except Exception:
                pass

        # If after_id is not present in this filtered visible set, real APIs generally return empty page rather than error.
        # We therefore do NOT reject "invalid cursor".
        if after_id is not None:
            ids = [w.get("id") for w in visible]
            if after_id in ids:
                idx = ids.index(after_id)
                visible = visible[idx + 1 :]
            else:
                visible = []

    page = visible[:limit]
    has_more = len(visible) > limit
    next_cursor = page[-1].get("id") if (has_more and page and isinstance(page[-1], dict)) else None

    # Update last_used_at on successful authenticated call (best-effort).
    # Ensure "no success without effect" does not apply here; this is a read and may have no mutable target.
    try:
        now = _now_iso_z()
        changed = False
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                k["last_used_at"] = now
                k["updated_at"] = now
                changed = True
                break
        if changed:
            _save("api_keys.json", api_keys)
    except Exception:
        pass

    _log_request(endpoint, api_key_id, workspace_id, 200, started)

    return {
        "object": "list",
        "data": page,
        "limit": limit,
        "total": len(page),
        "has_more": bool(has_more),
        "next_cursor": next_cursor,
    }

def workspaces_get(id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0458000" if __import__("os").path.isdir("./environment_mix/0458000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _resolve_auth():
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}
        cred = _extra.get("api_key") or _extra.get("api_key_id") or _extra.get("key")

        candidates = []
        for k in api_keys:
            if not isinstance(k, dict) or k.get("status") != "active":
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if not ws or ws.get("status") != "active":
                continue
            candidates.append((k, ws))

        if cred is None:
            return candidates[0] if candidates else (None, None)

        if not isinstance(cred, str) or not cred.strip():
            return (None, None)
        cred = cred.strip()
        for k, ws in candidates:
            if cred == k.get("id") or cred == k.get("key_prefix"):
                return (k, ws)
        return (None, None)

    def _log_request(endpoint, api_key_id, workspace_id, status, started_ts):
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        latency_ms = int(round((time.time() - started_ts) * 1000))
        reqs.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": status,
                "latency_ms": latency_ms,
                "created_at": _now_iso(),
            }
        )
        _save("request_logs.json", reqs)

    started = time.time()
    endpoint = "workspaces_get"

    if not isinstance(id, str) or not id.strip():
        try:
            _log_request(endpoint, None, None, "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "`id` must be a non-empty string.")
    id = id.strip()

    api_key, ws = _resolve_auth()
    if not api_key or not ws:
        try:
            _log_request(endpoint, None, None, "UNAUTHORIZED", started)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "Missing or invalid API key, or workspace not active.")

    # Visibility: only own workspace
    if id != ws.get("id"):
        try:
            _log_request(endpoint, api_key.get("id"), ws.get("id"), "NOT_FOUND", started)
        except Exception:
            pass
        return _err("NOT_FOUND", "Workspace not found.")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    target = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == id:
            target = w
            break
    if not target:
        try:
            _log_request(endpoint, api_key.get("id"), ws.get("id"), "NOT_FOUND", started)
        except Exception:
            pass
        return _err("NOT_FOUND", "Workspace not found.")

    try:
        _log_request(endpoint, api_key.get("id"), ws.get("id"), "OK", started)
    except Exception:
        pass

    return {"workspace": target}

