            if cred == k.get("id") or cred == k.get("key_prefix"):
                return (k, ws)
        return (None, None)

    def _log_request(endpoint, api_key_id, workspace_id, status_s, started_ts):
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        latency_ms = int(round((time.time() - started_ts) * 1000))
        reqs.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "status": status_s,
                "latency_ms": latency_ms,
                "created_at": _now_iso(),
            }
        )
        _save("request_logs.json", reqs)

    started = time.time()
    endpoint = "workspaces_update"

    if not isinstance(id, str) or not id.strip():
        try:
            _log_request(endpoint, None, None, "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "`id` must be a non-empty string.")
    id = id.strip()

    # Validate optional fields
    if name is not None and (not isinstance(name, str) or len(name.strip()) < 1):
        try:
            _log_request(endpoint, None, None, "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "`name` must be a non-empty string.")
    if retention_days is not None and (not isinstance(retention_days, int) or retention_days < 1 or retention_days > 3650):
        try:
            _log_request(endpoint, None, None, "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "`retention_days` must be an integer between 1 and 3650.")
    if max_thought_chars is not None and (not isinstance(max_thought_chars, int) or max_thought_chars < 1 or max_thought_chars > 200000):
        try:
            _log_request(endpoint, None, None, "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "`max_thought_chars` must be an integer between 1 and 200000.")
    if daily_thought_limit is not None and (not isinstance(daily_thought_limit, int) or daily_thought_limit < 0 or daily_thought_limit > 1000000):
        try:
            _log_request(endpoint, None, None, "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "`daily_thought_limit` must be an integer between 0 and 1000000.")
    if daily_char_limit is not None and (not isinstance(daily_char_limit, int) or daily_char_limit < 0 or daily_char_limit > 100000000):
        try:
            _log_request(endpoint, None, None, "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "`daily_char_limit` must be an integer between 0 and 100000000.")
    if status is not None and (not isinstance(status, str) or status not in ("active", "suspended", "deleted")):
        try:
            _log_request(endpoint, None, None, "VALIDATION_ERROR", started)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Invalid `status` value.")

    api_key, caller_ws = _resolve_auth()
    if not api_key or not caller_ws:
        try:
            _log_request(endpoint, None, None, "UNAUTHORIZED", started)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "Missing or invalid API key, or workspace not active.")

    # Permission model: only update own workspace (since no roles/ACLs are defined in schema)
    if id != caller_ws.get("id"):
        try:
            _log_request(endpoint, api_key.get("id"), caller_ws.get("id"), "UNAUTHORIZED", started)
        except Exception:
            pass
        return _err("UNAUTHORIZED", "Not permitted to update this workspace.")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    target = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == id:
            target = w
            break
    if not target:
        try:
            _log_request(endpoint, api_key.get("id"), caller_ws.get("id"), "NOT_FOUND", started)
        except Exception:
            pass
        return _err("NOT_FOUND", "Workspace not found.")

    # Enforce unique(name)
    if name is not None:
        new_name = name.strip()
        for w in workspaces:
            if not isinstance(w, dict):
                continue
            if w.get("id") != id and w.get("name") == new_name:
                try:
                    _log_request(endpoint, api_key.get("id"), id, "CONFLICT", started)
                except Exception:
                    pass
                return _err("CONFLICT", "Workspace name already exists.", field="name")
        target["name"] = new_name

    # Apply numeric updates
    if retention_days is not None:
        target["retention_days"] = retention_days
    if max_thought_chars is not None:
        target["max_thought_chars"] = max_thought_chars
    if daily_thought_limit is not None:
        target["daily_thought_limit"] = daily_thought_limit
    if daily_char_limit is not None:
        target["daily_char_limit"] = daily_char_limit

    # Status transition
    if status is not None and status != target.get("status"):
        cur = target.get("status")
        transitions = {
            "active": {"suspended", "deleted"},
            "suspended": {"active", "deleted"},
            "deleted": set(),
        }
        allowed = transitions.get(cur, set())
        if status not in allowed:
            try:
                _log_request(endpoint, api_key.get("id"), id, "INVALID_TRANSITION", started)
            except Exception:
                pass
            return _err(
                "INVALID_TRANSITION",
                "Requested workspace status transition is not allowed.",
                from_status=cur,
                to_status=status,
            )
        target["status"] = status

    target["updated_at"] = _now_iso()
    _save("workspaces.json", workspaces)

    try:
        _log_request(endpoint, api_key.get("id"), id, "OK", started)
    except Exception:
        pass

    return {"workspace": target}

def api_keys_list(workspace_id=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0458000" if __import__("os").path.isdir("./environment_mix/0458000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_cursor(c):
        if not c:
            return None
        if not isinstance(c, str):
            return "bad"
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return "bad"
            if obj.get("v") != 1 or obj.get("t") != "api_keys_list":
                return "bad"
            last_id = obj.get("last_id")
            if last_id is not None and not isinstance(last_id, str):
                return "bad"
            return last_id
        except Exception:
            return "bad"

    def _make_cursor(last_id):
        obj = {"v": 1, "t": "api_keys_list", "last_id": last_id}
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs
    if workspace_id is not None and not isinstance(workspace_id, str):
        return _err("VALIDATION_ERROR", "workspace_id must be a string")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "revoked"):
            return _err("VALIDATION_ERROR", "status must be one of: active, revoked")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    last_id = _parse_cursor(cursor)
    if last_id == "bad":
        return _err("VALIDATION_ERROR", "Invalid cursor")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")

    # Ambient authentication: find any active api_key whose workspace is active.
    # Since tool has no credential parameter, we pick a workable context from the store.
    caller_key = None
    caller_ws = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("workspace_id"), str):
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
            if ws and ws.get("status") == "active":
                caller_key = k
                caller_ws = ws
                break
    if not caller_key or not caller_ws:
        return _err("UNAUTHORIZED", "No active API key with an active workspace is available")

    target_ws_id = workspace_id or caller_ws.get("id")
    target_ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == target_ws_id), None)
    if not target_ws or target_ws.get("status") != "active":
        # Description: refuses if key invalid or workspace not active; here we model as unauthorized
        return _err("UNAUTHORIZED", "Workspace is not active or not accessible")

    # Enforce that caller can only list within its workspace (no explicit FORBIDDEN in this endpoint)
    if target_ws_id != caller_ws.get("id"):
        return _err("UNAUTHORIZED", "Cannot access requested workspace")

    # Request logging / quota: schema doesn't define request-log; usage_daily is specific to think calls.
    # Still update last_used_at for the authenticated key on successful auth (common behavior).
    # (Not a blanket mutation: only when we proceed.)
    # We'll persist this update as observable state.
    for k in api_keys:
        if k.get("id") == caller_key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = k.get("updated_at") or now_iso
            break
    _save("api_keys.json", api_keys)

    rows = []
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("workspace_id") != target_ws_id:
            continue
        if status is not None and k.get("status") != status:
            continue
        rows.append(k)

    # Sort by created_at desc then id for stability
    def _dt(s):
        if not isinstance(s, str):
            return ""
        return s
    rows.sort(key=lambda r: (_dt(r.get("created_at")), str(r.get("id"))), reverse=True)

    start_idx = 0
    if last_id:
        # Find the position after the row with id == last_id in the sorted list
        for i, r in enumerate(rows):
            if r.get("id") == last_id:
                start_idx = i + 1
                break

    page = rows[start_idx:start_idx + limit]
    has_more = start_idx + limit < len(rows)
    next_cursor = _make_cursor(page[-1]["id"]) if (has_more and page) else None

    # Never return key_hash; only metadata
    data = []
    for r in page:
        data.append({
            "id": r.get("id"),
            "workspace_id": r.get("workspace_id"),
            "name": r.get("name"),
            "status": r.get("status"),
            "key_prefix": r.get("key_prefix"),
            "last_used_at": r.get("last_used_at"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        })

    return {
        "object": "list",
        "data": data,
        "limit": limit,
        "total": len(rows),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def thought_logs_list(workspace_id=None, status=None, api_key_id=None, created_at_gte=None, created_at_lte=None, client_request_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0458000" if __import__("os").path.isdir("./environment_mix/0458000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_rfc3339(s):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, "type"
        try:
            # Support trailing Z
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc), None
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                # treat as UTC if naive (common)
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, "format"

    def _parse_cursor(c):
        if not c:
            return None
        if not isinstance(c, str):
            return "bad"
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return "bad"
            if obj.get("v") != 1 or obj.get("t") != "thought_logs_list":
                return "bad"
            last_id = obj.get("last_id")
            if last_id is not None and not isinstance(last_id, str):
                return "bad"
            return last_id
        except Exception:
            return "bad"

    def _make_cursor(last_id):
        obj = {"v": 1, "t": "thought_logs_list", "last_id": last_id}
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs
    if workspace_id is not None and not isinstance(workspace_id, str):
        return _err("VALIDATION_ERROR", "workspace_id must be a string")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("recorded", "redacted", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: recorded, redacted, deleted")
    if api_key_id is not None and not isinstance(api_key_id, str):
        return _err("VALIDATION_ERROR", "api_key_id must be a string")
    if client_request_id is not None and not isinstance(client_request_id, str):
        return _err("VALIDATION_ERROR", "client_request_id must be a string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    gte_dt, gte_err = _parse_rfc3339(created_at_gte)
    if gte_err == "type":
        return _err("VALIDATION_ERROR", "created_at_gte must be a string")
    if gte_err == "format":
        return _err("VALIDATION_ERROR", "created_at_gte must be an RFC3339 date-time")
    lte_dt, lte_err = _parse_rfc3339(created_at_lte)
    if lte_err == "type":
        return _err("VALIDATION_ERROR", "created_at_lte must be a string")
    if lte_err == "format":
        return _err("VALIDATION_ERROR", "created_at_lte must be an RFC3339 date-time")
    if gte_dt and lte_dt and gte_dt > lte_dt:
        return _err("VALIDATION_ERROR", "created_at_gte must be <= created_at_lte")

    last_id = _parse_cursor(cursor)
    if last_id == "bad":
        return _err("VALIDATION_ERROR", "Invalid cursor")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    thought_logs = _load("thought_logs.json")

    # Ambient authentication: must map to an active api_key and active workspace.
    caller_key = None
    caller_ws = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("workspace_id"), str):
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
            if ws and ws.get("status") == "active":
                caller_key = k
                caller_ws = ws
                break
    if not caller_key or not caller_ws:
        return _err("UNAUTHORIZED", "No active API key with an active workspace is available")

    target_ws_id = workspace_id or caller_ws.get("id")

    target_ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == target_ws_id), None)
    if not target_ws:
        return _err("NOT_FOUND", "Workspace not found")
    # Not visible if deleted/suspended (per business rules: no new logs; for listing, tool says NOT_FOUND if not visible)
    if target_ws.get("status") != "active":
        return _err("NOT_FOUND", "Workspace not found")

    # Access control: caller can only access its own workspace; tool mentions FORBIDDEN but allowed codes list doesn't include it.
    if target_ws_id != caller_ws.get("id"):
        return _err("UNAUTHORIZED", "Cannot access requested workspace")

    # Update last_used_at for the authenticated key
    for k in api_keys:
        if k.get("id") == caller_key.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = k.get("updated_at") or now_iso
            break
    _save("api_keys.json", api_keys)

    def _iso_to_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
                dt = datetime.datetime.fromisoformat(s).replace(tzinfo=datetime.timezone.utc)
            else:
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                else:
                    dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return None

    # Filter
    rows = []
    for r in thought_logs:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != target_ws_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if api_key_id is not None and r.get("api_key_id") != api_key_id:
            continue
        if client_request_id is not None and r.get("client_request_id") != client_request_id:
            continue
        if gte_dt or lte_dt:
            cdt = _iso_to_dt(r.get("created_at"))
            if cdt is None:
                continue
            if gte_dt and cdt < gte_dt:
                continue
            if lte_dt and cdt > lte_dt:
                continue
        rows.append(r)

    # Sort by created_at desc then id desc
    rows.sort(key=lambda r: (r.get("created_at") or "", str(r.get("id"))), reverse=True)

    start_idx = 0
    if last_id:
        for i, r in enumerate(rows):
            if r.get("id") == last_id:
                start_idx = i + 1
                break

    page = rows[start_idx:start_idx + limit]
    has_more = start_idx + limit < len(rows)
    next_cursor = _make_cursor(page[-1]["id"]) if (has_more and page) else None

    # Return full thought log rows (including thought text, which may already be redacted placeholder)
    data = []
    for r in page:
        data.append({
            "id": r.get("id"),
            "workspace_id": r.get("workspace_id"),
            "api_key_id": r.get("api_key_id"),
            "status": r.get("status"),
            "thought": r.get("thought"),
            "thought_sha256": r.get("thought_sha256"),
            "thought_chars": r.get("thought_chars"),
            "client_request_id": r.get("client_request_id"),
            "ip_address": r.get("ip_address"),
            "user_agent": r.get("user_agent"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        })

    return {
        "object": "list",
        "data": data,
        "limit": limit,
        "total": len(rows),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "latency_ms": int((time.time() - t0) * 1000),
    }
